  MAINNET_CODE,
  ROPSTEN_CODE,
  RINKEBY_CODE,
  KOVAN_CODE,
  GOERLI_CODE,
  ROPSTEN,
  RINKEBY,
  KOVAN,
  GOERLI,
  MAINNET
} = require('./network/enums');

const networkTypeToIdMap = {
  [ROPSTEN]: String(ROPSTEN_CODE),
  [RINKEBY]: String(RINKEBY_CODE),
  [KOVAN]: String(KOVAN_CODE),
  [GOERLI]: String(GOERLI_CODE),
  [MAINNET]: String(MAINNET_CODE)
};
