  timeout: 30000
});

class IncomingTransactionsController {
  constructor(opts = {}) {
    const {
      blockTracker,
      networkController,
      preferencesController
    } = opts;
    this.blockTracker = blockTracker;
    this.networkController = networkController;
    this.preferencesController = preferencesController;

    this.getCurrentNetwork = () => networkController.getProviderConfig().type;

    this._onLatestBlock = async newBlockNumberHex => {
      const selectedAddress = this.preferencesController.getSelectedAddress();
      const newBlockNumberDec = parseInt(newBlockNumberHex, 16);
      await this._update({
        address: selectedAddress,
        newBlockNumberDec
      });
    };

    const initState = Object.assign({
      incomingTransactions: {},
      incomingTxLastFetchedBlocksByNetwork: {
        [ROPSTEN]: null,
        [RINKEBY]: null,
        [KOVAN]: null,
        [GOERLI]: null,
        [MAINNET]: null
      }
    }, opts.initState);
    this.store = new ObservableStore(initState);
    this.preferencesController.store.subscribe(pairwise((prevState, currState) => {
      const {
        featureFlags: {
          showIncomingTransactions: prevShowIncomingTransactions
        } = {}
      } = prevState;
      const {
        featureFlags: {
          showIncomingTransactions: currShowIncomingTransactions
        } = {}
      } = currState;

      if (currShowIncomingTransactions === prevShowIncomingTransactions) {
        return;
      }

      if (prevShowIncomingTransactions && !currShowIncomingTransactions) {
        this.stop();
        return;
      }

      this.start();
    }));
    this.preferencesController.store.subscribe(pairwise(async (prevState, currState) => {
      const {
        selectedAddress: prevSelectedAddress
      } = prevState;
      const {
        selectedAddress: currSelectedAddress
      } = currState;

      if (currSelectedAddress === prevSelectedAddress) {
        return;
      }

      await this._update({
        address: currSelectedAddress
      });
    }));
    this.networkController.on('networkDidChange', async newType => {
      const address = this.preferencesController.getSelectedAddress();
      await this._update({
        address,
        networkType: newType
      });
    });
  }

  start() {
    const {
      featureFlags = {}
    } = this.preferencesController.store.getState();
    const {
      showIncomingTransactions
    } = featureFlags;

    if (!showIncomingTransactions) {
      return;
    }

    this.blockTracker.removeListener('latest', this._onLatestBlock);
    this.blockTracker.addListener('latest', this._onLatestBlock);
  }

  stop() {
    this.blockTracker.removeListener('latest', this._onLatestBlock);
  }

  async _update({
    address,
    newBlockNumberDec,
    networkType
  } = {}) {
    try {
      const dataForUpdate = await this._getDataForUpdate({
        address,
        newBlockNumberDec,
        networkType
      });
      await this._updateStateWithNewTxData(dataForUpdate);
    } catch (err) {
      log.error(err);
    }
  }

  async _getDataForUpdate({
    address,
    newBlockNumberDec,
    networkType
