  @param newState {object} - the update object
  @param note {string} - a optional note for the state change
  @returns {array}
*/


function generateHistoryEntry(previousState, newState, note) {
  const entry = jsonDiffer.compare(previousState, newState); // Add a note to the first op, since it breaks if we append it to the entry

  if (entry[0]) {
    if (note) entry[0].note = note;
    entry[0].timestamp = Date.now();
  }

  return entry;
}
/**
  Recovers previous txMeta state obj
  @returns {object}
*/


function replayHistory(_shortHistory) {
  const shortHistory = clone(_shortHistory);
  return shortHistory.reduce((val, entry) => jsonDiffer.applyPatch(val, entry).newDocument);
