"use strict";

var _errorKeys = require("../../../../ui/app/helpers/constants/error-keys");

const EthQuery = require('ethjs-query');

const {
  hexToBn,
  BnMultiplyByFraction,
  bnToHex
} = require('../../lib/util');

const log = require('loglevel');

const {
  addHexPrefix
} = require('ethereumjs-util');

const {
  SEND_ETHER_ACTION_KEY
} = require('../../../../ui/app/helpers/constants/transactions.js');

const SIMPLE_GAS_COST = '0x5208'; // Hex for 21000, cost of a simple send.

/**
tx-gas-utils are gas utility methods for Transaction manager
its passed ethquery
and used to do things like calculate gas of a tx.
@param {Object} provider - A network provider.
*/
class TxGasUtil {
  constructor(provider) {
    this.query = new EthQuery(provider);
  }
  /**
    @param txMeta {Object} - the txMeta object
    @returns {object} the txMeta object with the gas written to the txParams
  */


  async analyzeGasUsage(txMeta, getCodeResponse) {
    const block = await this.query.getBlockByNumber('latest', false);
    let estimatedGasHex;

    try {
      estimatedGasHex = await this.estimateTxGas(txMeta, block.gasLimit, getCodeResponse);
    } catch (err) {
      log.warn(err);
      txMeta.simulationFails = {
        reason: err.message,
        errorKey: err.errorKey,
        debug: {
          blockNumber: block.number,
          blockGasLimit: block.gasLimit
        }
      };

      if (err.errorKey === _errorKeys.TRANSACTION_NO_CONTRACT_ERROR_KEY) {
        txMeta.simulationFails.debug.getCodeResponse = err.getCodeResponse;
      }

      return txMeta;
    }

    this.setTxGas(txMeta, block.gasLimit, estimatedGasHex);
    return txMeta;
  }
  /**
    Estimates the tx's gas usage
    @param txMeta {Object} - the txMeta object
    @param blockGasLimitHex {string} - hex string of the block's gas limit
    @returns {string} the estimated gas limit as a hex string
  */


  async estimateTxGas(txMeta, blockGasLimitHex, getCodeResponse) {
    const txParams = txMeta.txParams; // check if gasLimit is already specified

    txMeta.gasLimitSpecified = Boolean(txParams.gas); // if it is, use that value

    if (txMeta.gasLimitSpecified) {
      return txParams.gas;
    }

    const recipient = txParams.to;
    const hasRecipient = Boolean(recipient); // see if we can set the gas based on the recipient

    if (hasRecipient) {
      // For an address with no code, geth will return '0x', and ganache-core v2.2.1 will return '0x0'
      const categorizedAsSimple = txMeta.transactionCategory === SEND_ETHER_ACTION_KEY;

      if (categorizedAsSimple) {
        // if there's data in the params, but there's no contract code, it's not a valid transaction
        if (txParams.data) {
          const err = new Error('TxGasUtil - Trying to call a function on a non-contract address'); // set error key so ui can display localized error message

          err.errorKey = _errorKeys.TRANSACTION_NO_CONTRACT_ERROR_KEY; // set the response on the error so that we can see in logs what the actual response was

          err.getCodeResponse = getCodeResponse;
          throw err;
        } // This is a standard ether simple send, gas requirement is exactly 21k


        txParams.gas = SIMPLE_GAS_COST; // prevents buffer addition

        txMeta.simpleSend = true;
        return SIMPLE_GAS_COST;
      }
