// Etc...
//

/**
 * Opens the browser popup for user confirmation
 */


function triggerUi() {
  extension.tabs.query({
    active: true
  }, tabs => {
    const currentlyActiveMetamaskTab = Boolean(tabs.find(tab => openMetamaskTabsIDs[tab.id]));

